async function nav(route,data={}){if(isAdminRoute(route)&&!isAdmin())route=currentUser()?'user-profile':'login';if(currentUser()&&['create','beauty-main','user-profile'].includes(route)){let existing=await resolveCurrentBeautyProfile();if(route==='create'&&existing&&existing.verification_status==='pending')route='pending'}if(route==='verify-info'&&S.route!=='verify-info')sessionStorage.removeItem(VOICE_WHATSAPP_OPENED);Object.assign(S,data,{route});save();if(route==='beauty-verifications'&&isAdmin())await loadAdminPending();if(route==='beauty-approved-providers'&&isAdmin())await loadAdminApproved();render();scrollTo(0,0)}
