function authField(id,label,type,placeholder,icon,required=true,autocomplete=''){return `<label class="auth-field-label" for="${id}">${label}</label><div class="auth-field"><span>${icon}</span><input id="${id}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${autocomplete?`autocomplete="${autocomplete}"`:''}></div>`}
function socialButtons(){return `<div class="auth-divider"><span>or continue with</span></div><button class="auth-social" onclick="socialAuth('google')"><img class="google-mark" src="google_g.svg" alt="">Continue with Google</button><button class="auth-social" onclick="socialAuth('facebook')"><b class="facebook-mark">f</b>Continue with Facebook</button>`}
function loginPage(){return `<div class="auth-page"><h1>Welcome back</h1><p class="auth-subtitle">Log in to continue to HerDay.</p><form class="auth-card" onsubmit="loginAccount(event)">${authField('loginEmail','Email','email','Enter your email','✉',true,'email')}${authField('loginPassword','Password','password','Enter your password','♙',true,'current-password')}<button type="button" class="auth-link forgot" onclick="forgotPassword()">Forgot Password?</button><button class="btn primary auth-primary" type="submit">Log In</button>${socialButtons()}</form><p class="auth-switch">Don't have an account? <button onclick="nav('signup')">Sign Up</button></p></div>`}
function signUpPage(){return `<div class="auth-page signup-page"><h1>Create your account</h1><p class="auth-subtitle">Join HerDay and make it yours.</p><form class="auth-card" onsubmit="createAccount(event)">${authField('signupFirst','First Name','text','Enter first name','♙',true,'given-name')}${authField('signupLast','Last Name','text','Enter last name','♙',true,'family-name')}${authField('signupEmail','Email','email','Enter your email','✉',true,'email')}${authField('signupCell','Cell Number <span>(Optional)</span>','tel','Enter cell number','⌕',false,'tel')}${authField('signupPassword','Password','password','Create a password','♙',true,'new-password')}${authField('signupConfirm','Confirm Password','password','Confirm your password','♙',true,'new-password')}<button class="btn primary auth-primary" type="submit">Create Account</button><p class="auth-terms">By creating an account, you agree to HerDay's<br><button type="button" onclick="showPlaceholder('Terms & Privacy Policy')">Terms &amp; Privacy Policy.</button></p>${socialButtons()}</form><p class="auth-switch">Already have an account? <button onclick="nav('login')">Log In</button></p></div>`}
function normalizeAccount(authUser,profile){return {id:authUser.id,email:authUser.email||'',firstName:profile.first_name||'',lastName:profile.last_name||'',cell:profile.cell_number||'',avatarPath:profile.avatar_path||'',photo:'',role:profile.role||'user',isBlocked:!!profile.is_blocked}}
async function signedStorageUrl(bucket,path){if(!path)return '';let {data,error}=await supabaseClient.storage.from(bucket).createSignedUrl(path,3600);return error?'':data.signedUrl}
async function databaseBeautyProfile(row){return {id:row.id,ownerId:row.owner_id,name:row.professional_name,about:row.about||'',photoPath:row.professional_photo_path||'',photo:await signedStorageUrl('beauty-profile-photos',row.professional_photo_path),cats:row.categories||[],services:row.services||[],areas:row.service_areas||[],phone:row.whatsapp_number||'',submittedAt:row.verification_submitted_at||null,verification:row.verification_status,verified:!!row.verified,isPublic:!!row.is_public}}
function hydrateBeauty(row,photo=''){if(!row){for(const k of ['beautyProfileId','newName','newAbout','newPhoto','newPhotoPath','newCats','newServices','newAreas','newPhone','verification','verificationSubmittedAt','verificationCorrection','beautyVerified','beautyPublic','beautyOwnerId'])delete S[k];save();return}Object.assign(S,{beautyProfileId:row.id,newName:row.professional_name,newAbout:row.about||'',newPhoto:photo,newPhotoPath:row.professional_photo_path||'',newCats:row.categories||[],newServices:row.services||[],newAreas:row.service_areas||[],newPhone:row.whatsapp_number||'',verification:row.verification_status,verificationSubmittedAt:row.verification_submitted_at,verificationCorrection:row.correction_reason?{reason:row.correction_reason,note:row.correction_note||''}:null,beautyVerified:!!row.verified,beautyPublic:!!row.is_public,beautyOwnerId:row.owner_id});save()}
async function resolveCurrentBeautyProfile(){let user=ACTIVE_AUTH_USER;if(!user){hydrateBeauty(null);return null}let {data,error}=await supabaseClient.from('beauty_profiles').select('*').eq('owner_id',user.id).maybeSingle();if(error)throw error;hydrateBeauty(data,data?await signedStorageUrl('beauty-profile-photos',data.professional_photo_path):'');return data}
async function loadCurrentAccount(){let {data:{user}}=await supabaseClient.auth.getUser();ACTIVE_AUTH_USER=user||null;ACTIVE_ACCOUNT=null;if(!user){hydrateBeauty(null);return}let {data:profile,error}=await supabaseClient.from('profiles').select('*').eq('id',user.id).single();if(error)throw error;ACTIVE_ACCOUNT=normalizeAccount(user,profile);ACTIVE_ACCOUNT.photo=await signedStorageUrl('profile-photos',ACTIVE_ACCOUNT.avatarPath);if(ACTIVE_ACCOUNT.isBlocked){await supabaseClient.auth.signOut();ACTIVE_AUTH_USER=null;ACTIVE_ACCOUNT=null;throw new Error('This account is blocked. Contact HerDay support.')}await resolveCurrentBeautyProfile()}
async function loadAdminPending(){if(!isAdmin()){ADMIN_PENDING=[];return}let {data,error}=await supabaseClient.from('beauty_profiles').select('*').eq('verification_status','pending').order('verification_submitted_at',{ascending:true});if(error)throw error;ADMIN_PENDING=await Promise.all((data||[]).map(databaseBeautyProfile))}
async function loadAdminApproved(){if(!isAdmin()){ADMIN_APPROVED=[];return}let {data,error}=await supabaseClient.from('beauty_profiles').select('*').eq('verification_status','approved').order('professional_name',{ascending:true});if(error)throw error;ADMIN_APPROVED=await Promise.all((data||[]).map(databaseBeautyProfile))}
async function loadApprovedBeauty(){let {data,error}=await supabaseClient.from('beauty_profiles').select('*').eq('verification_status','approved').eq('verified',true).eq('is_public',true);if(error){APPROVED_BEAUTY=[];return}APPROVED_BEAUTY=await Promise.all((data||[]).map(databaseBeautyProfile))}
async function bootstrapSupabase(){setBeauty(true);app().className='beauty-shell auth-shell';app().innerHTML='<div class="auth-page"><p class="auth-subtitle">Loading HerDay…</p></div>';try{await loadCurrentAccount();await loadApprovedBeauty();if(isAdmin())await loadAdminPending();if(!ACTIVE_ACCOUNT&&!['login','signup'].includes(S.route))S.route='login';else if(ACTIVE_ACCOUNT&&['login','signup'].includes(S.route))S.route=ACTIVE_ACCOUNT.role==='admin'?'admin-profile':'home';if(ACTIVE_ACCOUNT&&S.route==='create'&&S.beautyProfileId){if(S.verification==='pending')S.route='pending';else if(S.verification==='approved'){S.route='profile';S.provider=S.beautyProfileId}}save();render()}catch(error){console.error(error);S.route='login';save();render();alert(error.message||'Unable to connect to HerDay.')}}
async function createAccount(event){event.preventDefault();let first=$('#signupFirst').value.trim(),last=$('#signupLast').value.trim(),email=$('#signupEmail').value.trim().toLowerCase(),cell=$('#signupCell').value.trim(),password=$('#signupPassword').value,confirmPassword=$('#signupConfirm').value;if(!first||!last||!email||!password||!confirmPassword){alert('Please complete all required fields.');return}if(password!==confirmPassword){alert('Passwords do not match.');return}if(password.length<8){alert('Password must be at least 8 characters.');return}let {data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{first_name:first,last_name:last,cell_number:cell||null}}});if(error){alert(error.message);return}if(!data.session){alert('Account created. Please check your email to confirm your HerDay account.');nav('login');return}await loadCurrentAccount();S.route='home';save();render();scrollTo(0,0)}
async function loginAccount(event){event.preventDefault();let email=$('#loginEmail').value.trim().toLowerCase(),password=$('#loginPassword').value;let {error}=await supabaseClient.auth.signInWithPassword({email,password});if(error){alert('Email or password is incorrect.');return}try{await loadCurrentAccount();if(isAdmin())await loadAdminPending();S.route=isAdmin()?'admin-profile':'home';save();render();scrollTo(0,0)}catch(loadError){alert(loadError.message)}}
async function socialAuth(provider){let {error}=await supabaseClient.auth.signInWithOAuth({provider,options:{redirectTo:location.origin+location.pathname}});if(error)alert(`${provider==='google'?'Google':'Facebook'} sign-in is not configured yet: ${error.message}`)}
async function forgotPassword(){let email=$('#loginEmail')?.value.trim().toLowerCase();if(!email){alert('Enter your email first.');return}let {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});alert(error?error.message:'Password reset instructions have been sent if this account exists.')}
