async function savePersonalProfile(){let user=currentUser();if(!user)return;let first=$('#editFirst').value.trim(),last=$('#editLast').value.trim(),cell=$('#editCell').value.trim();if(!first||!last){alert('First and Last Name are required.');return}let oldPath=user.avatarPath||null,avatarPath=REMOVE_ACCOUNT_PHOTO?null:oldPath,file=$('#editPhoto').files?.[0];if(file){if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){alert('Use a JPEG, PNG or WebP photo no larger than 5 MB.');return}let ext={"image/jpeg":'jpg',"image/png":'png',"image/webp":'webp'}[file.type],path=`${user.id}/avatar-${Date.now()}.${ext}`,upload=await supabaseClient.storage.from('profile-photos').upload(path,file,{upsert:true});if(upload.error){alert(upload.error.message);return}avatarPath=path}let {error}=await supabaseClient.from('profiles').update({first_name:first,last_name:last,cell_number:cell||null,avatar_path:avatarPath}).eq('id',user.id);if(error){alert(error.message);return}if(oldPath&&oldPath!==avatarPath)await supabaseClient.storage.from('profile-photos').remove([oldPath]);REMOVE_ACCOUNT_PHOTO=false;await loadCurrentAccount();closeAdminDialog();render()}
