Object.assign(HORO_UI.ur,{view:'آج کا زائچہ دیکھیں'});Object.assign(HORO_UI.hi,{view:'आज का राशिफल देखें'});Object.assign(HORO_UI.bn,{view:'আজকের রাশিফল দেখুন'});Object.assign(HORO_UI.ar,{view:'شاهدي أبراج اليوم'});
function horoscopeDate(lang='en'){let locale={en:'en-US',ur:'ur-PK',hi:'hi-IN',bn:'bn-BD',ar:'ar'}[lang]||'en-US';return new Date().toLocaleDateString(locale,{month:'long',day:'numeric',year:'numeric'})}
function horoscopeHeader(back){return `<div class="horo-head"><button class="horo-back" aria-label="Back" onclick="nav('${back}')">←</button></div>`}
function setHoroLanguage(lang){S.horoLang=lang;save();render()}
function selectZodiac(name){S.horoSign=name;save();render()}
function openZodiac(name){S.horoSign=name||S.horoSign||'Libra';save();nav('horoscope-detail')}
function localizedSignName(index,lang){return (HORO_SIGN_NAMES[lang]||HORO_SIGN_NAMES.en)[index]||ZODIAC[index][0]}
function horoIcon(name){let paths={check:'<path d="m7 12 3 3 7-7"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.7-7.5 1.1-1.1a5.5 5.5 0 0 0 0-7.8Z"/>',career:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18M10 12v2h4v-2"/>',health:'<path d="M20 4c-7 0-12 3-14 8-1 3 1 7 5 8 6 1 10-6 9-16Z"/><path d="M4 21c3-6 7-10 12-13"/>',guidance:'<path d="m12 2.8 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.4l6.2-.9L12 2.8Z"/>',share:'<circle cx="18" cy="5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="19" r="2.5"/><path d="m8.2 10.8 7.5-4.4M8.2 13.2l7.5 4.4"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||''}</svg>`}
function languageSelector(lang){return `<div class="language-tabs" role="group" aria-label="Horoscope language">${HORO_LANGS.map(([k,n])=>`<button dir="auto" lang="${k}" class="${lang===k?'active':''}" onclick="setHoroLanguage('${k}')" aria-pressed="${lang===k}">${n}</button>`).join('')}</div>`}
function horoscopeSelection(){let lang=S.horoLang||'en',u=HORO_UI[lang]||HORO_UI.en,rtl=['ur','ar'].includes(lang),sign=S.horoSign||'Libra',selectedIndex=Math.max(0,ZODIAC.findIndex(x=>x[0]===sign)),z=ZODIAC[selectedIndex];return `<div class="horoscope-page selection ${rtl?'rtl-copy':''}" lang="${lang}" dir="ltr">${horoscopeHeader('home')}<header class="horo-title-block horo-localized" dir="${rtl?'rtl':'ltr'}"><h1 class="horo-page-title">${u.title}</h1><p class="horo-intro">${u.subtitle}</p><div class="horo-date">${horoscopeDate(lang)}</div></header><div class="horo-art selection-art"><img src="assets/horoscope-page1-artwork-web.webp" alt="Floral celestial illustration with crescent moons and constellation" width="1086" height="362"></div>${languageSelector(lang)}<section class="zodiac-section horo-localized" dir="${rtl?'rtl':'ltr'}"><h2>${u.choose}</h2><p>${u.chooseSub}</p><div class="zodiac-grid" dir="ltr">${ZODIAC.map(([n,s],i)=>`<button class="zodiac-card zodiac-tone-${i} ${n===z[0]?'selected':''}" onclick="selectZodiac('${n}')" aria-pressed="${n===z[0]}"><span class="zodiac-medallion">${s}︎</span><b dir="auto">${localizedSignName(i,lang)}</b>${n===z[0]?`<i class="selected-check">${horoIcon('check')}</i>`:''}</button>`).join('')}</div></section><section class="selected-zodiac-summary" dir="${rtl?'rtl':'ltr'}"><span class="summary-symbol">${z[1]}︎</span><div class="summary-copy"><h2>${localizedSignName(selectedIndex,lang)}</h2><p>${z[2]}</p><p>${cTraits(lang,z)}</p></div><button class="view-horoscope" onclick="openZodiac('${z[0]}')"><span>${u.view}</span>${horoIcon('arrow')}</button></section></div>`}
function cTraits(lang,z){return (HORO_COPY[lang]||HORO_COPY.en).traits||z[3]}
function horoscopeDetail(){let lang=S.horoLang||'en',sign=S.horoSign||'Libra',index=Math.max(0,ZODIAC.findIndex(x=>x[0]===sign)),z=ZODIAC[index],c=HORO_COPY[lang]||HORO_COPY.en,u=HORO_UI[lang]||HORO_UI.en,rtl=['ur','ar'].includes(lang);let insights=[['heart',u.love,c.love],['career',u.career,c.career],['health',u.health,c.health],['guidance',u.guidance,c.guidance]];return `<div class="horoscope-page detail ${rtl?'rtl-copy':''}" lang="${lang}" dir="ltr">${horoscopeHeader('horoscope')}<header class="horo-title-block horo-localized" dir="${rtl?'rtl':'ltr'}"><h1 class="horo-page-title">${u.title}</h1><div class="horo-date">${horoscopeDate(lang)}</div></header><section class="sign-identity" dir="${rtl?'rtl':'ltr'}"><span class="sign-symbol">${z[1]}︎</span><div class="sign-copy"><h2>${localizedSignName(index,lang)}</h2><p>${z[2]}</p><p class="sign-traits">${cTraits(lang,z)}</p></div></section>${languageSelector(lang)}<main class="horo-dynamic horo-localized" dir="${rtl?'rtl':'ltr'}"><h2 class="section-heading">${u.reading}</h2><section class="reading-card"><p>${c.reading}</p></section><div class="insight-grid">${insights.map(([icon,title,text])=>`<section class="insight-card"><div class="insight-title"><span class="insight-icon ${icon}">${horoIcon(icon)}</span><h2>${title}</h2></div><p>${text}</p></section>`).join('')}</div><h2 class="section-heading lucky-heading">${u.details}</h2><section class="lucky-card"><div><span class="lucky-item"><i class="lucky-visual swatch" aria-hidden="true"></i><small>${u.color}</small><b>${c.lucky}</b></span><span class="lucky-item"><i class="lucky-visual number" aria-label="6">6</i><small>${u.number}</small></span><span class="lucky-item"><i class="lucky-visual mood" aria-hidden="true">☺</i><small>${u.mood}</small><b>${c.mood}</b></span></div></section><button class="share-horo" onclick="shareHoroscope()">${horoIcon('share')}<span>${u.share}</span></button></main></div>`}
async function shareHoroscope(){let lang=S.horoLang||'en',index=Math.max(0,ZODIAC.findIndex(x=>x[0]===(S.horoSign||'Libra'))),sign=localizedSignName(index,lang),txt=`HerDay — ${sign} Daily Horoscope`;if(navigator.share){try{await navigator.share({title:'HerDay Daily Horoscope',text:txt});return}catch(e){if(e?.name==='AbortError')return}}try{await navigator.clipboard.writeText(txt);alert('Horoscope copied for sharing.')}catch(e){alert(txt)}}
function myBeautyPage(){if(!S.beautyProfileId)return head('My Beauty Profile','','beauty-main')+`<div class="bcard"><p class="muted">Profile unavailable.</p></div>`;return head('My Beauty Profile','','beauty-main')+`<div class="bcard owner-beauty-card"><div class="row"><span class="round-icon">♙</span><div><h2>${esc(S.newName||'Beauty Profile')}</h2><span class="status done">Verified ✓</span><div class="muted">${esc((S.newCats||[]).join(' • '))}</div></div></div>${S.newAbout?`<p class="muted owner-about">${esc(S.newAbout)}</p>`:''}</div><button class="btn primary" onclick="nav('create')">Edit Beauty Profile</button><button class="btn secondary" onclick="nav('profile',{provider:S.beautyProfileId})">View Public Profile</button>`}
function accountSettingsPage(){let u=currentUser();return `${profileHeader('Account Settings')}<div class="settings-list">${accountRow('▢','Change Password',`nav('change-password')`)}<div class="settings-static"><span>✉</span><div><b>Account Email</b><p>${esc(u?.email||'')}</p><small>Your account email cannot be changed here.</small></div></div><div class="settings-static"><span>♧</span><div><b>Notifications</b><p>Manage your HerDay notifications.</p></div><label class="switch"><input type="checkbox" ${u?.notificationsEnabled?'checked':''} onchange="updateNotificationsWeb(this.checked)"><i></i></label></div></div><h2 class="account-section-title">Danger Zone</h2><button class="danger-row" onclick="confirmDeleteAccount()"><span>♲</span><div><b>Delete Account</b><p>Permanently delete your HerDay account and data.</p></div><i>›</i></button>`}
function changePasswordPage(){return `${profileHeader('Change Password')}<div class="bcard content-card"><h2>Create a new password</h2><p class="muted">Use at least 8 characters.</p><label class="dialog-label">New Password</label><input id="newPassword" class="field" type="password" placeholder="Minimum 8 characters"><label class="dialog-label">Confirm New Password</label><input id="confirmNewPassword" class="field" type="password" placeholder="Confirm new password"></div><button class="btn primary" onclick="changePasswordWeb()">Update Password</button>`}
async function updateNotificationsWeb(enabled){let u=currentUser();if(!u)return;let {error}=await supabaseClient.from('profiles').update({notifications_enabled:enabled}).eq('id',u.id);if(error){alert('Could not update notifications.');render();return}ACTIVE_ACCOUNT={...u,notificationsEnabled:enabled};render()}
async function changePasswordWeb(){let p=$('#newPassword')?.value||'',c=$('#confirmNewPassword')?.value||'';if(p.length<8){alert('Password must be at least 8 characters.');return}if(p!==c){alert('Passwords do not match.');return}let {error}=await supabaseClient.auth.updateUser({password:p});if(error){alert('Could not update password.');return}alert('Password updated successfully.');nav('account-settings')}
async function confirmDeleteAccount(){if(!confirm('This permanently deletes your HerDay account and applicable owned data. This action cannot be undone.\n\nContinue only if you understand your account will be permanently deleted.'))return;let {error}=await supabaseClient.rpc('delete_own_account');if(error){alert('Account could not be deleted.');return}await supabaseClient.auth.signOut();ACTIVE_AUTH_USER=null;ACTIVE_ACCOUNT=null;S.route='login';save();render()}

window.nav=nav;window.openProfile=openProfile;window.loginAccount=loginAccount;window.createAccount=createAccount;window.socialAuth=socialAuth;window.forgotPassword=forgotPassword;window.signOut=signOut;window.showPlaceholder=showPlaceholder;window.showEditProfileDialog=showEditProfileDialog;window.savePersonalProfile=savePersonalProfile;window.nearMe=nearMe;window.closeLocationSearch=closeLocationSearch;window.locationInput=locationInput;window.selectLocation=selectLocation;window.areaSearch=areaSearch;window.pickArea=pickArea;window.toggleCat=toggleCat;window.chooseLocation=chooseLocation;window.addService=addService;window.removeService=removeService;window.editService=editService;window.selectProfilePhoto=selectProfilePhoto;window.addArea=addArea;window.removeArea=removeArea;window.saveCreate=saveCreate;window.openVerificationWhatsApp=openVerificationWhatsApp;window.confirmVoiceVerification=confirmVoiceVerification;window.startCamera=startCamera;window.closeCamera=closeCamera;window.recordStart=recordStart;window.recordStop=recordStop;window.retake=retake;window.submitVerification=submitVerification;window.contact=contact;window.markDone=markDone;window.confirmYes=confirmYes;window.confirmNo=confirmNo;window.submitReview=submitReview;window.openBeautyVerifications=()=>nav('beauty-verifications');window.openBeautyReview=openBeautyReview;window.toggleAdminCheck=toggleAdminCheck;window.showApproveBeautyDialog=showApproveBeautyDialog;window.showCorrectionDialog=showCorrectionDialog;window.closeAdminDialog=closeAdminDialog;window.approveBeautyVerification=approveBeautyVerification;window.sendBeautyCorrection=sendBeautyCorrection;
window.setHoroLanguage=setHoroLanguage;window.selectZodiac=selectZodiac;window.openZodiac=openZodiac;window.shareHoroscope=shareHoroscope;window.updateNotificationsWeb=updateNotificationsWeb;window.changePasswordWeb=changePasswordWeb;window.confirmDeleteAccount=confirmDeleteAccount;
window.render=render;
